-- Shared by all users: a word is generated by the LLM once and reused.
create table lexeme (
    id              bigint generated always as identity primary key,
    lang            varchar(8)   not null,
    text            varchar(200) not null,
    normalized_text varchar(200) not null,
    part_of_speech  varchar(50),
    ipa             varchar(200),
    ipa_source      varchar(20) check (ipa_source in ('WIKTIONARY', 'ESPEAK', 'LLM')),
    created_at      timestamptz  not null default now(),
    constraint lexeme_lang_normalized_text_uq unique (lang, normalized_text),
    constraint lexeme_ipa_with_source_ck check ((ipa is null) = (ipa_source is null))
);

create table lexeme_meaning (
    lexeme_id   bigint       not null references lexeme (id) on delete cascade,
    native_lang varchar(8)   not null,
    meaning     varchar(500) not null,
    primary key (lexeme_id, native_lang)
);

create table example (
    id         bigint generated always as identity primary key,
    lexeme_id  bigint        not null references lexeme (id) on delete cascade,
    text       varchar(1000) not null check (btrim(text) <> ''),
    level      varchar(2)    not null check (level in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
    created_at timestamptz   not null default now(),
    constraint example_lexeme_text_uq unique (lexeme_id, text)
);

create table example_translation (
    example_id  bigint        not null references example (id) on delete cascade,
    native_lang varchar(8)    not null,
    translation varchar(1000) not null,
    primary key (example_id, native_lang)
);
